"""Russian glass research UI; dynamic log data is rendered as text, never HTML."""
PAGE="""<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>USB Lab — исследование</title><link rel="stylesheet" href="/research.css"></head><body><main>
<header class="glass"><small>USB LAB · ИССЛЕДОВАТЕЛЬСКИЙ СТЕНД</small><h1>Наблюдать. Повторять. Исследовать.</h1><p>UART и SSH · оригинальные журналы · повтор сохранённых конфигураций</p></header>
<section class="glass row"><label>Токен доступа <input id="token" type="password" autocomplete="off" placeholder="Из терминала Pi"></label><button id="login">Войти</button><button id="logout">Выйти</button><span id="connection">Вход не выполнен</span><p class="muted">Токен хранится в памяти страницы и не теряется между вкладками. Не публикуйте его.</p></section>
<p id="error" class="error" role="status"></p><nav class="row"><button data-tab="run" class="selected">Запуск</button><button data-tab="logs">Журналы</button><button data-tab="results">Результаты и повторы</button><button data-tab="archive">Архив</button></nav>
<section id="run" class="page"><div class="cards"><article class="glass"><small>СОСТОЯНИЕ</small><h2 id="stage">Ожидание входа</h2><p id="target">—</p></article><article class="glass"><small>ПРОГРЕСС</small><h2 id="progress">—</h2><progress id="bar" value="0" max="1"></progress></article><article class="glass"><small>КАНАЛ НАБЛЮДЕНИЯ</small><h2 id="capture-state">—</h2><p id="capture-bytes">—</p></article></div><article class="glass"><h2>Управление кампанией</h2><p id="settings">Параметры берутся из конфигурации стенда.</p><div class="row"><select id="mode" aria-label="Режим"><option value="uart">UART</option><option value="ssh">SSH</option></select><button id="apply">Выбрать режим</button><button id="start">Начать кампанию</button><button id="stop" class="danger">Остановить попытки</button><button id="resume">Продолжить выбранную</button></div><p class="muted">Остановка не прерывает начатый анализ. Выход из сайта не останавливает кампанию.</p></article><details class="glass"><summary>Технические сведения</summary><pre id="technical"></pre></details></section>
<section id="logs" class="page" hidden><article class="glass"><h2>Журнал выбранного запуска</h2><div class="row"><select id="source" aria-label="Источник"></select><select id="lines" aria-label="Строки"><option>100</option><option selected>300</option><option>1000</option></select><select id="level" aria-label="Уровень"><option value="all">Все сообщения</option><option value="critical">Критические маркеры</option><option value="error">Ошибки</option><option value="warning">Предупреждения</option><option value="info">Информация</option></select><input id="query" maxlength="128" placeholder="Поиск в загруженном окне"></div><div class="row"><input id="offset" type="number" min="0" placeholder="Смещение; пусто — хвост"><button id="log-refresh">Обновить</button><button id="tail">Последние строки</button><label><input id="live" type="checkbox" checked> Обновлять каждые 2 секунды</label><label><input id="scroll" type="checkbox" checked> Автопрокрутка</label></div><p id="log-scope" class="muted"></p><div id="log-view" class="log-view"></div><div class="row"><button id="fragment">Скачать окно с фильтрами</button><button id="raw-fragment">Скачать байты окна</button><button id="whole">Скачать полный файл</button></div><p class="muted">Подсветка — эвристика, не доказательство panic или уязвимости. Оригиналы не изменяются.</p></article></section>
<section id="results" class="page" hidden><article class="glass"><h2>Результаты попыток</h2><p class="muted">После panic/Oops сначала восстановите хост. Повтор конфигурации и wire_seed не гарантирует ту же последовательность USB-обменов.</p><div class="row"><select id="attempt" aria-label="Попытка"></select><input id="attempt-manual" placeholder="Старая попытка: attempt-000123"><button id="replay">Повторить попытку</button></div><div id="attempt-cards"></div></article><article class="glass"><h2>Результат повтора и источник</h2><div id="comparison"></div></article><article class="glass"><h2>Анализ и диагностика</h2><div id="analysis"></div></article></section>
<section id="archive" class="page" hidden><article class="glass"><h2>Материалы для исследования</h2><p>ZIP доступных разрешённых материалов содержит манифест SHA-256. Полнота захвата неизвестна; снимок не атомарный. Логи могут содержать секреты.</p><button id="bundle">Скачать пакет запуска</button><div id="downloads" class="row"></div></article></section>
<section class="glass row"><label>Выбранный запуск <select id="campaign"></select></label><button id="refresh">Обновить историю</button><p id="selected-info" class="muted"></p></section><footer>Доступ через loopback / SSH-туннель · данные остаются на стенде</footer></main><script src="/research.js"></script></body></html>""".encode('utf-8')
STYLE="""*{box-sizing:border-box}body{margin:0;color:#eef3ff;background:radial-gradient(ellipse at 5% 0%,#393072 0%,transparent 48%),radial-gradient(ellipse at 100% 45%,#143c51 0%,transparent 45%),#0b1123;font:15px/1.65 system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:28px}.glass{background:linear-gradient(135deg,#34405b88,#17233ba6);backdrop-filter:blur(20px);border:1px solid #aec4f02b;box-shadow:0 18px 48px #0003;border-radius:22px;padding:24px;margin:18px 0}h1{font-size:clamp(26px,3vw,40px);letter-spacing:-1px;margin:12px 0}h2{margin:12px 0}small{color:#b2baff;letter-spacing:2px;font-size:11px}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.cards h2{font-size:28px}button,input,select{font:inherit;border-radius:11px;padding:9px 13px;border:1px solid #8096c955;max-width:100%}input,select{background:#0b132bc9;color:#eef3ff}select option{background:#142039}button{color:#fff;background:linear-gradient(130deg,#7860dc,#4962ac);cursor:pointer;transition:filter .15s}button:hover{filter:brightness(1.15)}button:disabled{opacity:.4;cursor:not-allowed}nav button{background:transparent;color:#bdc9df}nav .selected{background:#6872cb55;border-color:#a9b8ff}.danger{background:#953a51}.muted,footer{color:#b0c0da;font-size:13px}.error{color:#ffb6c2;white-space:pre-wrap}.log-view{max-height:560px;min-height:160px;overflow:auto;background:#071022bb;border:1px solid #6c86b844;border-radius:13px;padding:9px}.log-line{font:12px/1.7 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;border-left:3px solid transparent;padding:7px 10px}.critical{border-color:#ff6576;background:#d7414a26}.error.log-line{border-color:#ffae71;background:#ff88471a}.warning{border-color:#f0cb66;background:#efbc3317}.badge{font:11px system-ui;color:#c6d5ed;margin-right:12px}.critical .badge{color:#ffadba}.warning .badge{color:#ffe09b}.attempt-card{border:1px solid #7994c744;border-radius:13px;padding:15px;margin:13px 0}pre{font:12px/1.7 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#09112799;border-radius:12px;padding:16px}progress{width:100%;accent-color:#b1a4ff}footer{text-align:center;margin:26px 0}[hidden]{display:none!important}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #beafff;outline-offset:3px}@media(max-width:800px){main{padding:14px}.glass{padding:17px}.cards{grid-template-columns:1fr}.row input:not([type=checkbox]),.row select{max-width:100%}}""".encode('utf-8')
SCRIPT="""'use strict';
const el=id=>document.getElementById(id),labels={critical:'КРИТИЧЕСКИЙ МАРКЕР',error:'ОШИБКА',warning:'ПРЕДУПРЕЖДЕНИЕ',info:'ИНФОРМАЦИЯ'},stages={idle:'Готов к работе',preparing:'Предпроверка',running:'USB-попытки',stopping:'Остановка',analyzing:'Анализ журналов',completed:'Завершено',stopped:'Остановлено',failed:'Ошибка'};
let token='',epoch=0,abort=new AbortController(),busy=false,tab='run',state=null,log=null,lastActive=null;
function node(tag,text,cls){const n=document.createElement(tag);n.textContent=String(text??'');if(cls)n.className=cls;return n;}
function clear(){epoch++;abort.abort();abort=new AbortController();token='';busy=false;state=log=null;lastActive=null;el('token').value='';for(const id of ['error','technical','settings','selected-info','log-scope'])el(id).textContent='';for(const id of ['campaign','attempt','source','attempt-cards','comparison','analysis','downloads','log-view'])el(id).replaceChildren();el('connection').textContent='Вход не выполнен';el('stage').textContent='Ожидание входа';for(const id of ['target','progress','capture-state','capture-bytes'])el(id).textContent='—';el('bar').value=0;}
async function api(path,body){const gen=epoch,o={signal:abort.signal,headers:{Authorization:'Bearer '+token}};if(body!==undefined){o.method='POST';o.headers['Content-Type']='application/json';o.body=JSON.stringify(body);}const r=await fetch(path,o),v=await r.json();if(gen!==epoch)throw new Error('Сеанс изменился');if(r.status===401){clear();el('error').textContent='Токен отклонён. Войдите заново.';throw new Error('Токен отклонён. Войдите заново.');}if(!r.ok)throw new Error(v.error||'Запрос не выполнен');return v;}
async function download(path,name){const gen=epoch;try{const r=await fetch(path,{signal:abort.signal,headers:{Authorization:'Bearer '+token}});if(!r.ok)throw new Error((await r.json()).error);if(Number(r.headers.get('Content-Length'))>134217728&&!confirm('Большой файл потребует память браузера. Можно скачать участок. Продолжить?'))return;const data=await r.blob();if(gen!==epoch)return;const u=URL.createObjectURL(data),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);}catch(e){if(gen===epoch&&e.name!=='AbortError')el('error').textContent=e.message;}}
function file(campaign,area,name,start,end){const q={campaign,area,name};if(start!==undefined)q.start=String(start);if(end!==undefined)q.end=String(end);return '/api/file?'+new URLSearchParams(q);}
function addFile(id,area,name){const b=node('button',area+' / '+name);b.onclick=()=>download(file(id,area,name),id+'-'+name);el('downloads').append(b);}
function query(){const campaign=el('campaign').value,p=el('source').value.split('|');if(!campaign||p.length!==2)return null;const q={campaign,area:p[0],name:p[1],lines:el('lines').value,level:el('level').value,query:el('query').value};if(el('offset').value!=='')q.offset=el('offset').value;return q;}
async function logs(force=false){if(!token||(!force&&!el('live').checked))return;const s=window.getSelection();if(!force&&s&&!s.isCollapsed&&el('log-view').contains(s.anchorNode))return;const q=query();if(!q)return;const v=await api('/api/log?'+new URLSearchParams(q));if(new URLSearchParams(query()||{}).toString()!==new URLSearchParams(q).toString())return;log=v;el('log-scope').textContent='Байты '+v.start+'–'+v.end+' из '+v.size+' · поиск только в окне · пропущено совпадений: '+v.omitted_matching_rows+(v.partial_head||v.partial_tail?' · границы строки обрезаны':'')+' · полнота неизвестна';el('log-view').replaceChildren();for(const r of v.rows){const n=node('div','', 'log-line '+r.level);n.append(node('span',labels[r.level]+' · '+r.start,'badge'),node('span',r.text));n.title=r.reason+(r.display_truncated?' · длинная строка сокращена':'');el('log-view').append(n);}if(!v.rows.length)el('log-view').append(node('p','В этом окне нет подходящих сообщений.','muted'));if(el('scroll').checked)el('log-view').scrollTop=el('log-view').scrollHeight;}
async function details(id){const d=await api('/api/details?'+new URLSearchParams({campaign:id}));if(el('campaign').value!==id)return;el('selected-info').textContent='Идентификатор: '+id+' · '+d.metadata.mode.toUpperCase();const oldAttempt=el('attempt').value,oldSource=el('source').value;for(const x of ['attempt','source','attempt-cards','analysis','downloads','comparison'])el(x).replaceChildren();function option(value,text){const o=node('option',text);o.value=value;el('source').append(o);}option('capture|uart.raw','Журнал хоста');option('capture|events.jsonl','События приёмника');option('capture|chunks.jsonl','Индекс захвата');if(d.metadata.mode==='ssh')option('capture|ssh-stderr.log','Диагностика SSH');for(const a of d.attempts){const number=Number(a.id.slice(8))+1,o=node('option','Попытка №'+number);o.value=a.id;el('attempt').append(o);option(a.id+'|executor.log','Исполнитель · №'+number);const r=a.result,c=node('article','', 'attempt-card');c.append(node('h3','Попытка №'+number),node('p',!r?'Результат ещё не сохранён':r.infrastructure_error?'Ошибка исполнителя / инфраструктуры: '+r.infrastructure_error:r.interrupted?'Прервана':r.window_completed?'Окно завершено; enumeration отдельно не подтверждена':'Окно не завершено'));const b=node('button','Повторить эту попытку');b.disabled=Boolean(state?.busy);b.onclick=()=>replay(a.id,id);c.append(b);el('attempt-cards').append(c);for(const name of ['config.json','started.json','window.json','result.json','executor.log'])addFile(id,a.id,name);}if([...el('attempt').options].some(o=>o.value===oldAttempt))el('attempt').value=oldAttempt;if([...el('source').options].some(o=>o.value===oldSource))el('source').value=oldSource;for(const name of ['campaign.json','checkpoint.json','selection.json','transport-analysis.json','replay-source.json','replay-result.json'])addFile(id,'campaign',name);for(const name of ['uart.raw','chunks.jsonl','events.jsonl'])addFile(id,'capture',name);if(d.metadata.mode==='ssh')addFile(id,'capture','ssh-stderr.log');for(const x of d.exports){el('analysis').append(node('h3',x.area),node('pre',JSON.stringify(x.error||x.summary,null,2)));for(const name of x.files)addFile(id,x.area,name);}if(!d.exports.length)el('analysis').append(node('p','Экспорты анализа ещё не созданы или отсутствуют.','muted'));const c=await api('/api/replay-info?'+new URLSearchParams({campaign:id})),source=c['replay-source.json'],result=c['replay-result.json'];if(el('campaign').value!==id)return;if(source){el('comparison').append(node('p','Источник: '+source.campaign+' / '+source.attempt+(source.observation_changed?' · канал наблюдения изменён':'')),node('p',result?'Совпадение сохранённой конфигурации: '+(result.same_configuration===true?'да':result.same_configuration===false?'нет':'не проверено')+' · подтверждение воспроизведения сбоя: не установлено':'Повтор ещё не сохранил итоговый результат'),node('pre',JSON.stringify(result||source,null,2)));}else el('comparison').append(node('p','Исходный запуск. Выберите попытку для повтора.','muted'));}
async function refresh(){if(!token||busy)return;busy=true;const gen=epoch;try{const s=await api('/api/state');state=s;el('connection').textContent='Доступ подтверждён';el('stage').textContent=stages[s.stage]||s.stage;el('target').textContent=s.mode.toUpperCase()+' · '+(s.target.host?s.target.user+'@'+s.target.host:s.target.port);el('progress').textContent=s.completed+' / '+s.iterations;el('bar').max=s.iterations;el('bar').value=s.completed;el('capture-state').textContent=({new:'Ещё не открыт',starting:'Подключение',connected:'Подключён',reconnecting:'Переподключение',failed:'Ошибка',stopped:'Остановлен'})[s.capture?.state]||'Нет активного захвата';el('capture-bytes').textContent='Принято байтов: '+(s.capture?.bytes_received||0)+' · полнота неизвестна';el('settings').textContent='Попыток: '+s.iterations+' · окно: '+s.seconds+' с · seed: '+s.seed+(s.replay_source?' · повтор сохранённой конфигурации':'');el('technical').textContent=JSON.stringify(s,null,2);el('error').textContent=s.error||'';for(const id of ['apply','start','resume','replay','bundle'])el(id).disabled=s.busy;el('stop').disabled=!s.busy||s.stage==='analyzing';const rows=await api('/api/history'),old=el('campaign').value,keep=s.active&&s.active!==lastActive?s.active:rows.some(r=>r.id===old)?old:(s.active||rows[0]?.id||'');lastActive=s.active;el('campaign').replaceChildren();for(const r of rows){const o=node('option',r.mode.toUpperCase()+' · '+r.id.slice(0,8)+' · обновлён '+new Date(r.modified_ns/1000000).toLocaleString('ru-RU'));o.value=r.id;el('campaign').append(o);}el('campaign').value=keep;if(keep){await details(keep);if(tab==='logs')await logs();}}catch(e){if(gen===epoch&&e.name!=='AbortError')el('error').textContent=e.message;}finally{if(gen===epoch)busy=false;}}
async function action(path,body){if(!token)return;try{await api(path,body);await refresh();}catch(e){el('error').textContent=e.message;}}
function replay(attempt,campaign=el('campaign').value){if(!campaign||!attempt){el('error').textContent='Выберите запуск и попытку';return;}if(confirm('Повторить '+attempt+'? Одна USB-попытка с сохранённой конфигурацией и wire_seed. Сначала восстановите хост. Длительность — из источника, канал и quiet-окна — текущие.'))action('/api/replay',{campaign,attempt});}
for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{tab=b.dataset.tab;for(const p of document.querySelectorAll('.page'))p.hidden=p.id!==tab;for(const n of document.querySelectorAll('[data-tab]'))n.classList.toggle('selected',n===b);if(tab==='logs')logs(true).catch(e=>el('error').textContent=e.message);};
el('login').onclick=()=>{const value=el('token').value;clear();token=value;el('token').value='';refresh();};el('logout').onclick=clear;el('refresh').onclick=refresh;el('campaign').onchange=refresh;el('apply').onclick=()=>action('/api/mode',{mode:el('mode').value});el('stop').onclick=()=>action('/api/stop',{});el('start').onclick=()=>{if(confirm('Начать USB-кампанию на выделенном стенде?'))action('/api/start',{});};el('resume').onclick=()=>{if(confirm('Продолжить совместимую кампанию?'))action('/api/resume',{campaign:el('campaign').value});};el('replay').onclick=()=>replay(el('attempt-manual').value.trim()||el('attempt').value);
el('log-refresh').onclick=()=>logs(true).catch(e=>el('error').textContent=e.message);el('tail').onclick=()=>{el('offset').value='';el('log-refresh').click();};for(const id of ['source','lines','level'])el(id).onchange=()=>el('log-refresh').click();el('fragment').onclick=()=>{const q=query();if(!q||!log||log.campaign!==q.campaign||log.area!==q.area||log.name!==q.name){el('error').textContent='Сначала обновите окно журнала';return;}const u=URL.createObjectURL(new Blob([JSON.stringify(log,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=q.campaign+'-fragment.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);};el('raw-fragment').onclick=()=>{const q=query();if(q&&log&&log.campaign===q.campaign&&log.area===q.area&&log.name===q.name)download(file(q.campaign,q.area,q.name,log.start,log.end),q.campaign+'-raw-fragment.bin');};el('whole').onclick=()=>{const q=query();if(q)download(file(q.campaign,q.area,q.name),q.campaign+'-'+q.name);};el('bundle').onclick=()=>{const campaign=el('campaign').value;if(campaign)download('/api/bundle?'+new URLSearchParams({campaign}),campaign+'-research.zip');};setInterval(refresh,2000);
""".encode('utf-8')
